    // 功能函数：一维滚动 DP 求最长公共子串
    public static String lcsSubstring(String a, String b) {
        int m = b.length();
        int[] dp = new int[m + 1];  // dp[j]：以 b[j-1] 结尾的公共后缀长度（当前行）
        int bestLen = 0, endPos = 0; // 记录最大长度及其在 a 中的结束位置

